class Solution {public String[][] solve(String[] words){HashMap<String,ArrayList<String>> groups=new HashMap<>();for(String word:words){char[] key=word.toCharArray();Arrays.sort(key);groups.computeIfAbsent(new String(key),k->new ArrayList<>()).add(word);}ArrayList<ArrayList<String>> out=new ArrayList<>(groups.values());for(ArrayList<String> g:out)Collections.sort(g);out.sort((a,b)->a.get(0).compareTo(b.get(0)));String[][] result=new String[out.size()][];for(int i=0;i<out.size();i++)result[i]=out.get(i).toArray(new String[0]);return result;}}